interface PreviewPaneProps {
  content: string;
  collapsed: boolean;
  onToggleCollapse: () => void;
  scrollRef?: React.RefObject<HTMLDivElement>;
  onScroll?: (e: React.UIEvent<HTMLDivElement>) => void;
}

export function PreviewPane({ content, collapsed, onToggleCollapse, scrollRef, onScroll }: PreviewPaneProps) {
  if (collapsed) {
    return (
      <CollapsedTab onClick={onToggleCollapse} title="Show preview">
        <PanelRightOpen size={14} />
        <VerticalLabel>Preview</VerticalLabel>
      </CollapsedTab>
    );
  }

  return (
    <Pane>
      <PaneHeader>
        <PaneTitle>Preview</PaneTitle>
        <CollapseBtn onClick={onToggleCollapse} title="Collapse preview">
          <PanelRightClose size={15} />
        </CollapseBtn>
      </PaneHeader>
      <ScrollArea ref={scrollRef} onScroll={onScroll}>
        <Article>
          <ReactMarkdown
            remarkPlugins={[remarkGfm, remarkMath, remarkCallouts]}
            rehypePlugins={[rehypeRaw, rehypeKatex]}
            components={{
              div({ node, children, ...props }) {
                const calloutType = (props as any)['data-callout'] as string | undefined;
                if (calloutType) return <div data-callout={calloutType}>{children}</div>;
                return <div {...props}>{children}</div>;
              },
              pre: ({ children }) => <>{children}</>,
              code({ className, children }) {
                const lang = /language-(\w+)/.exec(className ?? '')?.[1];
                const code = String(children).replace(/\n$/, '');
                if (lang === 'mermaid') return <MermaidBlock code={code} />;
                if (lang === 'chart') return <ChartBlock code={code} />;
                if (lang === 'clock') return <ClockBlock code={code} />;
                if (lang || code.includes('\n')) return <CodeBlock lang={lang} code={code} />;
                return <code className={className}>{children}</code>;
              },
            }}
          >
            {content}
          </ReactMarkdown>
        </Article>
      </ScrollArea>
    </Pane>
  );
}
